add(id=6, title="Feasibility and project planning", last_verified=V, prerequisites=["Modules 4, 5"],
 objectives=["Estimate the work a review requires and the resources needed.", "Run a feasibility pilot: eligible-study count, extractable data, dependence.", "Decide go / narrow / switch design before writing a protocol."],
 why="Many reviews stall at extraction because too few studies report usable data. A one-week pilot is cheaper than a failed six-month project.",
 plain="""Feasibility asks: *can this question be answered with the evidence that exists, by the team I have, in the time I have?* Check (1) **volume** - how many studies; (2) **data** - do they report effect + variance (or the inputs); (3) **comparability** - same outcome, direction, scale; (4) **independence** - labs, shared controls; (5) **skills** - statistics, searching, subject expertise; (6) **time** - searching, screening, extraction, verification, analysis, writing.""",
 intermediate="""**Pilot protocol.** Run the draft search in one database, screen a random sample (e.g. 100 records), and record: proportion potentially eligible; for the eligible ones, the proportion reporting n, mean/SD (or events); how many share controls or come from the same group. Extrapolate to estimate eligible studies and usable studies. Rules of thumb are only that: with fewer than ~5 usable studies a meta-analysis is fragile; with many but incomparable studies, a structured synthesis or scoping review may be right.
**Time.** Published analyses of registered reviews suggest systematic reviews commonly take many months with several people (Borah et al. 2017); environmental reviews show similar patterns (Haddaway & Westgate 2018). Treat these as orders of magnitude, not promises - a solo first review often takes longer.
**Go / narrow / switch.** Narrow the question (one outcome, one taxon) if volume is high and heterogeneous; broaden it if volume is tiny; switch to a scoping review if the aim is mapping; stop if novelty fails.""",
 advanced="""Feasibility also includes *statistical* feasibility: the number of independent units, the expected τ², and the planned moderators determine whether the analysis can say anything. A review with 6 studies cannot support meta-regression on 3 moderators. Plan the minimal credible analysis and a pre-specified fallback (e.g. SWiM). Budget verification (second extractor/author contact) explicitly; it is the first thing cut and the commonest source of avoidable error.""",
 assumptions=["The pilot sample is random, not the first 100 relevant-looking records.", "Eligibility criteria used in the pilot match the draft protocol."],
 worked_example="""Pilot: 100 records screened -> 22 potentially eligible (22%). Search returned 900 records -> ~200 eligible. Full-text check of 20: 12 report n, mean and a variance (60%) -> ~120 usable. 9 of 20 come from 3 groups (shared protocols) -> dependence must be modelled. Decision: **go**, but narrow to one device/protocol family, pre-specify lab as a cluster, and budget 2x extraction time. (Illustrative numbers.)""",
 examples=[("Preclinical","Few labs publish most studies: clustering."),("Clinical","Many trials but heterogeneous outcomes: choose one."),("Ecology","Many effect sizes per study: multilevel needed."),("Education","Outcome measures differ by test."),("Microbiology","Detection limits and log scales.")],
 mistakes=["Skipping the pilot.", "Counting records as studies.", "Ignoring dependence until analysis.", "No time for verification.", "Choosing the topic by how easy it looks to publish."],
 misconceptions=[("'Large literature = feasible.'","Usable data and independence matter more than volume."),("'A review is quick with software.'","Screening and extraction dominate time.")],
 controversies=["Minimum number of studies for a meta-analysis.", "How much narrowing is acceptable."],
 decision_tree=[("Enough eligible studies (pilot)?","No -> broaden, scoping review, or stop."),("Usable data in most?","No -> contact authors? else structured synthesis."),("Dependence high?","Plan multilevel/robust methods with a statistician."),("Resources match?","No -> reduce scope.")],
 exercises=["Run a 100-record pilot and fill the numbers above for your topic.", "List three reasons your pilot sample might not be representative.", "Draft a fallback analysis if only 5 studies are usable."],
 integrity="Do not select the topic by publishability alone. Report feasibility limits honestly in the protocol.",
 further=["borah2017","haddaway2018time","page2021ee"], application="**Milestone 3:** complete the feasibility memo (pilot counts, usable-data %, dependence, time plan, decision).",
 checklist=["Pilot done on a random sample", "Usable-data proportion estimated", "Dependence assessed", "Fallback analysis written", "Decision logged"],
 quiz=[dict(q="Why use a random sample for the pilot?", opts=["It is faster.","To avoid over-optimistic eligibility estimates from hand-picked records.","Journals require it.","It lowers cost."], ans=1, why="Hand-picked samples bias estimates."),
  dict(q="22 of 100 sampled records look eligible; the search found 900. Rough eligible count?", opts=["22","~200","900","~22%"], ans=1, why="0.22 × 900 ≈ 198.", numeric=True),
  dict(q="Which is a feasibility problem even with 100 studies?", opts=["None.","Most lack variances or share control groups.","They are in English.","They are recent."], ans=1, why="Usable data and independence determine analysis."),
  dict(q="When might a scoping review be better?", opts=["When aiming to map evidence/gaps rather than estimate an effect.","Always.","When you dislike statistics.","When k is large."], ans=0, why="Different purpose (Munn 2018)."),
  dict(q="Time estimates from published analyses should be treated as...", opts=["Guarantees","Orders of magnitude","Minimums","Irrelevant"], ans=1, why="They vary by team and topic.")])

add(id=9, title="Bibliographic databases: choosing where to search", last_verified=V, prerequisites=["Module 5"],
 objectives=["Explain why one database is never enough.", "Choose databases by discipline, coverage and access.", "Record platform, date and coverage limitations."],
 why="Databases differ in coverage, indexing and search syntax. Evidence on combinations and on academic search systems shows that choice affects what you find.",
 plain="""Think in layers: (1) **subject databases** (e.g. PubMed/MEDLINE for biomedicine; Embase; ERIC for education; AGRIS/AGRICOLA/CAB Abstracts for agriculture; Web of Science/Scopus multidisciplinary); (2) **registries** (trial/protocol registries); (3) **preprint servers** (bioRxiv, medRxiv, Europe PMC preprints); (4) **grey literature** and theses; (5) **citation chasing**. Some are free (PubMed, Europe PMC, OpenAlex), some need subscriptions (Embase, Web of Science, Scopus, CAB Abstracts). Never bypass paywalls; use your library or colleagues with access.""",
 intermediate="""Bramer et al. (2017) examined which database combinations reach high recall for systematic reviews in a prospective exploratory study; Gusenbauer & Haddaway (2020) evaluated academic search systems' suitability for systematic reviews. (Cited as further reading; their abstracts were not examined here.) Practical consequences: use at least two or three subject-appropriate databases, treat Google Scholar as a supplement, record the platform (e.g. Ovid vs EBSCO changes syntax), and document access limits ('Embase not accessible') honestly - a missing database is a limitation, not a secret.
**Export formats.** RIS and NBIB are common; keep the *raw export unchanged* and log counts.""",
 advanced="""Coverage overlaps heavily within biomedicine but differs for ecology, agriculture and social science; language and regional coverage vary. APIs (PubMed E-utilities, Crossref, OpenAlex) enable reproducible retrieval and citation chasing, subject to terms of use and rate limits. Reproducible search scripts should log query, date, API version and counts. Database coverage statements change; verify on the provider's official page rather than relying on tables from papers.""",
 assumptions=["You can access the databases you list, or you document limits.","Search dates are recorded at time of searching."],
 worked_example="""Fly-lifespan review: PubMed (free) + Europe PMC (free, preprints) + Web of Science or Scopus (institutional access?) + bioRxiv for preprints; citation chasing of included studies in OpenAlex. In the Search Log record: database, platform/interface, date, exact query, filters, counts, export file. If only PubMed and Europe PMC are accessible, state it as a limitation.""",
 examples=[("Clinical","MEDLINE + Embase + CENTRAL + trial registries."),("Plant","AGRIS/AGRICOLA/CAB + Web of Science."),("Education","ERIC + PsycINFO + Scopus."),("Ecology","Web of Science + Scopus + CEE resources."),("Microbiology","PubMed + Embase + preprints.")],
 mistakes=["Searching only PubMed for non-biomedical topics.","Not logging platform and date.","Trusting an AI summary as a database.","Ignoring preprints and registries.","Bypassing paywalls."],
 misconceptions=[("'Google Scholar is enough.'","Its coverage and reproducibility limits make it a supplement."),("'More databases always better.'","Diminishing returns; relevance and access matter.")],
 controversies=["Value of Embase over MEDLINE+others for a given topic.","Role of Google Scholar."],
 decision_tree=[("Biomedical/life science?","PubMed + Embase (+Europe PMC)."),("Education/social?","ERIC, PsycINFO, Scopus."),("Agriculture/environment?","AGRIS/AGRICOLA/CAB + WoS/Scopus."),("Always","registries, preprints, citation chasing.")],
 exercises=["List databases for your topic with access status (free/subscription/not available).","Search the same concept in two databases; compare counts and top records.","Write a limitations sentence for databases you could not access."],
 integrity="Do not claim a database was searched unless it was. Do not bypass access restrictions.",
 further=["bramer2017","gusenbauer2020","rethlefsen2021","page2021ee"], application="**Milestone 5:** choose and justify your database list; log access limits.",
 checklist=["Database list justified","Access limits documented","Registries and preprints considered","Platform/date logged"],
 quiz=[dict(q="Which is a legitimate response to lacking Embase access?", opts=["Claim it was searched.","State it as a search limitation and consider alternatives/colleagues with access.","Use a paywall bypass.","Ignore it."], ans=1, why="Transparency; no circumvention."),
  dict(q="Why record the platform?", opts=["Syntax and indexing differ by interface (e.g. Ovid vs EBSCO).","Journals require colours.","It is optional.","To save time."], ans=0, why="PRISMA-S asks for it."),
  dict(q="Google Scholar should be...", opts=["The only source","A supplement with documented limits","Banned","A registry"], ans=1, why="Reproducibility limits."),
  dict(q="Which databases are free?", opts=["PubMed and Europe PMC","Embase","Web of Science","CAB Abstracts"], ans=0, why="PubMed/Europe PMC are free; others typically subscription."),
  dict(q="Raw exports should be...", opts=["Edited for clarity","Kept unchanged","Deleted after import","Merged by hand"], ans=1, why="Preserves provenance.")])

add(id=13, title="Reference management: libraries, identifiers and verification", last_verified=V, prerequisites=["Module 9"],
 objectives=["Use RIS/BibTeX/NBIB and identifiers (DOI, PMID) correctly.", "Verify references against records; detect retractions/corrections.", "Keep raw exports separate from working libraries."],
 why="Citation errors and fabricated references are an integrity risk, especially with AI-generated text. Identifiers make verification mechanical.",
 plain="""A reference manager (e.g. Zotero) stores records and formats citations. Key identifiers: **DOI** (resolves to the publisher record), **PMID** (PubMed), **ORCID** (author). Verify every reference you cite by resolving its DOI/PMID and comparing title, authors, journal and year. Check for **retractions, corrections and expressions of concern** before citing. Preprints and published versions are different records of the same work.""",
 intermediate="""Workflow: export from each database (raw, unchanged) -> import to a *project library* -> deduplicate (Module 14) -> screen. Keep the raw files in the project archive. When citing in the manuscript, pull metadata from the DOI (e.g. Crossref) rather than retyping. MetaLab's `tools/verify_refs.py` demonstrates this: it rejects a record whose author or year does not match the registry - it caught several wrong DOIs recalled from memory during this project (see correction history). Verification of *existence* is not verification that the paper *supports your claim*.""",
 advanced="""Metadata quality varies: missing DOIs, truncated author lists, inconsistent journal names. Retraction status is tracked by publishers and the Retraction Watch database (check current availability and terms). Reference lists are also a search method (backward chasing). For living reviews, store stable identifiers and retrieval dates.""",
 assumptions=["DOIs/PMIDs are present or recoverable.", "You check retraction status near submission, not only at import."],
 worked_example="""Cited DOI 10.1111/1365-2745.12261 for a plant-ecology meta-analysis guide. Resolving it showed an unrelated paper (first author Pérez, freezing resistance) -> the DOI was wrong. Searching by title found the right record (Koricheva & Gurevitch 2014, DOI ...12224). This real error is in the correction history.""",
 examples=[("Clinical","Check retraction notices for included trials."),("Preclinical","Preprint -> published version mapping."),("Ecology","Book chapters have chapter DOIs."),("Education","Reports without DOIs: cite stable URL + date."),("All","Never cite from an AI answer without resolving the record.")],
 mistakes=["Retyping citations.","Citing without opening the record.","Ignoring retractions.","Overwriting raw exports.","Trusting AI-provided references."],
 misconceptions=[("'A reference with a DOI is real.'","A DOI can be mistyped to another paper; resolve and compare."),("'Existence = support.'","Read the source for the claim.")],
 controversies=["Reliance on single metadata sources.","Handling grey literature without DOIs."],
 decision_tree=[("Has DOI/PMID?","Resolve and compare metadata."),("No identifier?","Locate the source manually; cite stable URL."),("Preprint?","Check for the published version."),("Near submission","Re-check retractions.")],
 exercises=["Resolve 5 references in your draft and compare title/author/year.","Find a published version of a preprint you plan to cite.","Write a one-paragraph reference verification procedure for your project."],
 integrity="Never fabricate or guess references or DOIs. Do not cite papers you have not examined for the claim.",
 further=["bramer2016dedup","page2021ee","rethlefsen2021"], application="**Milestone 6/13:** verify every manuscript reference by identifier; keep raw exports.",
 checklist=["Raw exports archived","Identifiers resolved","Retractions checked","Preprint/published mapped"],
 quiz=[dict(q="Existence of a DOI record proves...", opts=["The paper supports your claim.","Only that the record exists with that metadata.","Peer review quality.","No retraction."], ans=1, why="Existence ≠ support."),
  dict(q="What should you do with raw database exports?", opts=["Edit them","Keep them unchanged in the archive","Delete","Merge manually"], ans=1, why="Provenance."),
  dict(q="Which tells you a DOI was mistyped?", opts=["Resolving it shows a different title/authors.","It is long.","It has slashes.","It is lower-case."], ans=0, why="Compare metadata."),
  dict(q="Retraction status should be checked...", opts=["Once at import","Near submission as well","Never","Only for preprints"], ans=1, why="Status changes."),
  dict(q="AI-suggested references must be...", opts=["Trusted","Verified against real records before use","Cited as is","Used in tables"], ans=1, why="Hallucinated citations occur.")])

add(id=14, title="Deduplication: exact, fuzzy and relational", last_verified=V, prerequisites=["Module 13"],
 objectives=["Apply exact and fuzzy matching with human confirmation.", "Distinguish duplicate records from multiple reports of one study.", "Keep an audit trail and make merges reversible."],
 why="Duplicates inflate counts and distort PRISMA flow; wrongly merging distinct records loses studies.",
 plain="""**Exact**: same DOI/PMID or identical normalised title+year. **Fuzzy**: similar titles with year/author agreement - candidates only; a human confirms. **Relational**: a preprint vs article, a conference abstract vs full paper, multiple reports of one study - these are *linked*, not discarded; the *study* is counted once.
MetaLab never deletes: duplicates are flagged and reversible, and every decision is in the audit log.""",
 intermediate="""Automated rules have false positives (similar titles in a series; corrigenda; different studies by one group) and false negatives (translated titles; missing DOIs). Bramer et al. (2016) describe a stepwise EndNote procedure with human checks. Always dedupe *before* screening but keep the original counts for PRISMA ('records identified', 'duplicates removed'). Record the method.""",
 advanced="""Blocking (indexing on rare tokens) avoids O(n²) comparisons; similarity thresholds trade sensitivity for specificity; tune on a labelled sample from your own libraries. Distinguish record-level from report-level from study-level deduplication: PRISMA 2020 counts reports and studies separately. Preprint-published pairs often have different DOIs.""",
 assumptions=["Original records are preserved.", "Fuzzy matches are never auto-merged."],
 worked_example="""Two records: 'Endurance exercise extends lifespan in Drosophila melanogaster males' (2020, J Aging, DOI a) and '...male flies' (2021, bioRxiv, DOI b). Title similarity 0.93, year diff 1, same first author, different DOIs -> *candidate: preprint <-> published*. Human decision: link as reports of one study; extract once from the more complete report.""",
 examples=[("Clinical","Trial registry + publication + conference abstract."),("Preclinical","Preprint + article."),("Ecology","Dataset paper + analysis paper."),("Education","Report + journal article."),("All","Corrections/errata.")],
 mistakes=["Auto-merging fuzzy matches.","Deleting duplicates.","Counting reports as studies.","Not recording the method."],
 misconceptions=[("'Same title = same study.'","Series and corrigenda share titles."),("'Different DOI = different study.'","Preprints and articles differ.")],
 controversies=["Acceptable similarity thresholds.","Whether to screen preprints separately."],
 decision_tree=[("Same DOI/PMID?","Exact duplicate."),("Similar title, close year, same author?","Candidate: human review."),("Different versions of one work?","Link as reports of one study.")],
 exercises=["In the Virtual Lab, run exact then fuzzy dedup and explain each decision.","Find a preprint/article pair in your field and link them.","Draft your dedup methods paragraph."],
 integrity="Never discard records silently; report counts at each step.", further=["bramer2016dedup","page2021ee"],
 application="**Milestone 6:** document the dedup procedure and counts for PRISMA.", checklist=["Exact then fuzzy with human review","Reports linked to studies","Counts recorded","Audit trail kept"],
 quiz=[dict(q="A preprint and its published article should be...", opts=["Both counted as separate studies","Linked as reports of one study","Deleted","Merged without a record"], ans=1, why="One study, two reports."),
  dict(q="Fuzzy matches are...", opts=["Merged automatically","Candidates requiring human confirmation","Ignored","Always wrong"], ans=1, why="Risk of false positives."),
  dict(q="Why keep raw counts?", opts=["PRISMA flow needs identified vs removed","Aesthetics","Speed","Journals ban deletion"], ans=0, why="Transparency."),
  dict(q="Identical title can occur for...", opts=["Corrigenda and article series","Never","Only preprints","Only reviews"], ans=0, why="Different records."),
  dict(q="Dedup should be reversible because...", opts=["Errors happen and must be correctable","Rules","Speed","Habit"], ans=0, why="Auditability.")])

add(id=15, title="Study screening: independence, calibration and agreement", last_verified=V, prerequisites=["Modules 7, 14"],
 objectives=["Run title/abstract then full-text screening with documented reasons.", "Calibrate, compute and interpret Cohen's kappa.", "Explain single versus independent duplicate screening and AI-assisted screening limits."],
 why="Selection bias enters here. Transparent, reproducible screening is what separates a systematic review from a literature summary.",
 plain="""Screen **title/abstract** against pre-specified criteria (be inclusive: 'uncertain' advances), then **full text** (record a reason for each exclusion). Use independent duplicate screening when feasible; otherwise document the limitation. **Calibrate** first on 20-50 records and refine unclear criteria *in the protocol, with dates*. Measure agreement (percent agreement and Cohen's kappa) and resolve conflicts by discussion or a third reviewer.""",
 intermediate="""Cohen's kappa corrects agreement for chance: κ=(po−pe)/(1−pe) (Cohen 1960; McHugh 2012 give a practical discussion). It depends on prevalence: with most records excluded, κ can be low despite high agreement - always report both. Landis & Koch (1977) benchmarks are conventions, not thresholds of validity.
**Single vs double screening.** A methodological review compared single and conventional double screening (Waffenschmidt et al. 2019); single screening can miss relevant studies, so if used, say so and consider mitigations (second reviewer on a sample/excluded records). **AI/active-learning tools** can prioritise records but are not independent human reviewers, and their stopping rules need validation; MetaLab refuses to record AI as a reviewer.""",
 advanced="""Report recall of screening by a second reviewer on a random sample of excluded records to estimate missed eligible studies. Active-learning stopping criteria (e.g. N consecutive irrelevant records) are heuristics with failure modes; document. Blinding reviewers to each other's decisions until conflicts are resolved reduces anchoring.""",
 assumptions=["Criteria are stable after calibration (changes logged).", "Reviewers decide independently before comparing."],
 formulas=[dict(name="Cohen's kappa", tex=r"\kappa=\frac{p_o-p_e}{1-p_e}", symbols={"p_o":"observed agreement","p_e":"agreement expected by chance from marginals"})],
 worked_example="""50 records, two reviewers: both include 20, both exclude 15, A includes/B excludes 5, A excludes/B includes 10. po=35/50=0.70; A includes 25/50, B includes 30/50 -> pe=0.5·0.6+0.5·0.4=0.50; κ=(0.70−0.50)/(1−0.50)=**0.40**. Agreement 70% but κ only 0.40 -> discuss disagreements, refine criteria, re-calibrate.""",
 examples=[("Clinical","Two independent reviewers + third adjudicator."),("Preclinical","Solo reviewer: document limitation; sample verification."),("Ecology","Multilingual records: translation plan."),("Education","Grey literature screening rules."),("All","Active learning for large searches (assist only).")],
 mistakes=["Excluding at title when unsure.","No exclusion reasons.","Changing criteria silently.","Reporting only κ.","Treating AI as a reviewer."],
 misconceptions=[("'High agreement means good screening.'","Both could share a misunderstanding."),("'Kappa above 0.8 is required.'","Context-dependent convention.")],
 controversies=["Single vs double screening.","Use/stopping rules of active learning."],
 decision_tree=[("Can two humans screen independently?","Yes -> do; No -> single + verification sample."),("κ low?","Discuss, refine criteria (log), recalibrate."),("Large set?","Prioritisation tools allowed; humans decide.")],
 exercises=["Compute κ for the example by hand and in the app.","Practise the Virtual Lab screening conflicts.","Write your exclusion reason list."],
 integrity="Document criteria changes with dates; never present AI as an independent reviewer; keep exclusion reasons for all full-text exclusions.",
 further=["mchugh2012","cohen1960","landis1977","waffenschmidt2019","page2021ee"], application="**Milestone 6:** calibrate, screen, record reasons, compute agreement, document limits.",
 checklist=["Calibration done","Reasons recorded","Agreement reported (percent + kappa)","Conflicts resolved and logged","Limitations stated"],
 quiz=[dict(q="po=0.70, pe=0.50. Kappa?", opts=["0.40","0.20","0.70","0.50"], ans=0, why="(0.70-0.50)/(1-0.50)=0.40.", numeric=True),
  dict(q="Why can kappa be low when agreement is high?", opts=["Prevalence/marginals inflate expected chance agreement.","Bug","Small n always","Bias"], ans=0, why="McHugh 2012."),
  dict(q="At title/abstract stage, unsure records should...", opts=["Be excluded","Advance to full text","Be deleted","Be asked to AI"], ans=1, why="Inclusive screening."),
  dict(q="Can AI be recorded as the second reviewer?", opts=["Yes","No - it is not an independent human reviewer","Only with logs","Only for titles"], ans=1, why="Integrity rule."),
  dict(q="Full-text exclusions require...", opts=["A recorded reason","Nothing","A kappa","Two reasons"], ans=0, why="PRISMA flow needs reasons.")])

add(id=16, title="PRISMA flow diagrams: records, reports and studies", last_verified=V, prerequisites=["Modules 14, 15"],
 objectives=["Define records, reports and studies as PRISMA 2020 does.", "Build a flow diagram whose counts reconcile.", "Spot inconsistent counts."],
 why="The flow diagram is the audit trail of selection. Counts that do not add up signal errors and undermine trust.",
 plain="""PRISMA 2020 flow: **identified** records (by source) -> duplicates removed -> **screened** -> excluded -> **reports sought** -> reports not retrieved -> **assessed for eligibility** -> excluded **with reasons** -> **studies included** (with their reports). One *study* can have several *reports*. Counts must reconcile at every box.""",
 intermediate="""Reconciliation rules: identified − duplicates = screened; screened − excluded = reports sought; sought − not retrieved = assessed; assessed − excluded = included reports. Exclusion reasons should be mutually exclusive, with each report assigned the *first* applicable reason (state your rule). MetaLab derives counts from stored decisions and warns about inconsistencies (e.g. exclusions without reasons). The PRISMA 2020 statement and explanation & elaboration paper define items and the flow template (Page et al. 2021a,b).""",
 advanced="""Updated reviews and reviews with other methods (citation searching, registers) use extended templates. For living reviews, show cumulative and per-update flows. Report counts per database where possible (PRISMA-S).""",
 assumptions=["All decisions are recorded.", "Reasons use pre-specified categories."],
 worked_example="""Identified 120; duplicates 20 -> screened 100; excluded 80 -> sought 20; not retrieved 0 -> assessed 20; excluded 12 (wrong organism 7, no controls 5) -> included 8 studies. Check: 120−20=100; 100−80=20; 20−12=8. ✓""",
 examples=[("Clinical","Registry records as separate source."),("Preclinical","Preprints counted as reports."),("Ecology","Citation chasing source."),("Education","Reports vs studies for multi-report programmes."),("All","Update flow.")],
 mistakes=["Counts that do not reconcile.","Missing reasons.","Counting reports as studies.","Not stating the reason-assignment rule."],
 misconceptions=[("'The diagram is decoration.'","It is a verifiable record."),("'One reason per report is arbitrary.'","State a consistent rule.")],
 controversies=["Level of detail on reasons.","Counting preprints."],
 decision_tree=[("Do boxes reconcile?","No -> find missing decisions."),("Reasons present for every exclusion?","No -> complete."),("Studies vs reports?","Link in Extraction tab.")],
 exercises=["Reconcile the Virtual Lab PRISMA counts.","Create a diagram with an intentional error and find it.","Write the reason-assignment rule."],
 integrity="Never adjust counts to look neat. Report all numbers as recorded.", further=["page2021","page2021ee","rethlefsen2021"],
 application="**Milestone 6:** produce the flow diagram from stored decisions; resolve every warning.", checklist=["Boxes reconcile","Reasons complete","Studies vs reports linked","Diagram exported"],
 quiz=[dict(q="Identified 120, duplicates 20, screened?", opts=["100","140","120","20"], ans=0, why="120−20.", numeric=True),
  dict(q="A study with a conference abstract and a paper is...", opts=["Two studies","One study, two reports","Excluded","Duplicate record to delete"], ans=1, why="PRISMA 2020 distinction."),
  dict(q="Exclusions at full text need...", opts=["Reasons","Nothing","A kappa","Journals' approval"], ans=0, why="Required."),
  dict(q="Counts that fail to reconcile indicate...", opts=["Missing/incorrect decisions to fix","Normal rounding","Software failure only","Nothing"], ans=0, why="Audit signal."),
  dict(q="PRISMA 2020 explanation & elaboration is...", opts=["A software","Guidance explaining each reporting item","A database","A registry"], ans=1, why="Page et al. 2021b.")])

add(id=17, title="Data extraction framework: forms, units and dependence", last_verified=V, prerequisites=["Modules 4, 7"],
 objectives=["Design an extraction form fitted to the review type.", "Define experimental unit and handle multiple arms/outcomes/time points.", "Pilot and version the form."],
 why="The form encodes your analysis plan. Fields you forget cannot be recovered cheaply later.",
 plain="""Extract: study/report identifiers; design; population/organism details; intervention/exposure details; comparator; outcomes (definition, time point, unit); sample sizes **at the unit of analysis**; summary data (mean, SD, n or events); funding/conflicts; risk-of-bias information; notes. Add fields for **shared control group IDs**, **multiple outcomes/time points** and **data source location**. Pilot on 3-5 studies, revise, then freeze (version it).""",
 intermediate="""Different review types need different forms (MetaLab provides preclinical, clinical, observational, ecological, qualitative and scoping templates). Decide the primary outcome and time point *a priori* to avoid cherry-picking. For multi-arm studies avoid reusing the control n in several comparisons (split or model dependence). Keep data as reported *and* as transformed (Module 20). Mathes et al. (2017) review extraction-error frequency and ways to improve extraction quality (cited as further reading).""",
 advanced="""Hierarchical structure (study > experiment > group > time point > outcome) maps to database tables and later to multilevel models. Stable identifiers (study, report, experiment, effect size) allow traceability from manuscript numbers to source pages. Extraction in a structured tool beats spreadsheets for audit trails; version every form change.""",
 assumptions=["Primary outcome fixed in the protocol.", "Unit of analysis defined."],
 worked_example="""Fly lifespan: study S001, report S001-R1, experiment E1 (males, 25 °C), groups ctrl/treat, fields: n_vials, mean_lifespan_days, sd, control_group_id, source (Table 2, p. 4). A second experiment E2 (females) shares the same control cohort -> flagged as dependent.""",
 examples=[("Clinical","Intention-to-treat population, time point."),("Preclinical","Strain, sex, age, housing, units."),("Ecology","Site, species, phylogeny id."),("Education","Classroom clustering, test form."),("Qualitative","Themes, quotes, context.")],
 mistakes=["No pilot.","Fly n as n.","No control IDs.","Extracting many outcomes without a plan.","Changing the form silently."],
 misconceptions=[("'More fields = better.'","Extract what the analysis needs."),("'One form fits all.'","Design-specific forms.")],
 controversies=["Single vs double extraction.","How many outcomes to extract."],
 decision_tree=[("Quantitative synthesis?","Include n, mean, SD/events, unit."),("Qualitative?","Themes/context fields."),("Scoping?","Charting fields.")],
 exercises=["Customise a form for your review and pilot on 3 studies.","List fields needed for your planned model.","Define IDs for study/report/experiment/effect."],
 integrity="Do not change extraction rules after seeing results without logging it.", further=["mathes2017","jones2005","page2021ee"],
 application="**Milestone 7:** build and pilot the extraction form; freeze v1.0.", checklist=["Pilot done","Unit of analysis defined","Control IDs included","Form versioned"],
 quiz=[dict(q="Why add a control_group_id field?", opts=["To detect dependence from shared controls","Looks neat","Required by PRISMA","For funding"], ans=0, why="Dependence."),
  dict(q="When is the primary outcome fixed?", opts=["After seeing results","In the protocol before extraction","After analysis","By journal"], ans=1, why="Avoid cherry-picking."),
  dict(q="Which is the correct n for lifespan in vials?", opts=["Flies","Vials (independent units)","Labs","Days"], ans=1, why="Unit of analysis."),
  dict(q="Forms should be...", opts=["Versioned and piloted","Changed freely","Hidden","Fixed forever"], ans=0, why="Traceability."),
  dict(q="Different review types need...", opts=["Different forms","The same","No form","Only text"], ans=0, why="Design-specific.")])

add(id=19, title="Graph digitisation and unavailable data", last_verified=V, prerequisites=["Module 18"],
 objectives=["Digitise graphs transparently and label values as reconstructed.", "Contact authors appropriately.", "Handle missing data without fabrication."],
 why="Key results are often shown only in figures. Digitisation introduces error you must acknowledge; missing data cannot be invented.",
 plain="""When numbers appear only in a figure, tools such as WebPlotDigitizer let you calibrate axes and click data points. Record: figure ID, software/version, calibration points, extracted values, and **label as reconstructed** with uncertainty. Contact corresponding authors (with your approval) before relying on digitised data. If still unavailable, record *missing with a reason*; do not substitute guesses.""",
 intermediate="""Studies have assessed digitisation reliability (e.g. Drevon et al. 2016 evaluated intercoder reliability and validity of WebPlotDigitizer; cited as further reading, abstract not examined). Error depends on figure resolution, marker overlap and axis scales. Best practice: two independent digitisers on a sample, compare, use mean/consensus, run a sensitivity analysis excluding reconstructed values. Survival curves: reconstruct data only with numbers at risk and clear steps; treat as estimated.""",
 advanced="""Digitised SE bars may be SD or SE or CI - check the legend. Log axes need careful calibration. For censored/survival data, reconstruction algorithms need assumptions; evaluate against studies with reported numbers. Propagate uncertainty: treat digitised values as measured with error (e.g. inflate variance) in sensitivity analyses.""",
 assumptions=["Axis scales and error-bar meaning are stated in the figure legend.","Resolution is adequate."],
 worked_example="""A bar chart shows treated 53 ± error bar to 55. After calibration you read 53.2 and 55.1; the legend says error bars are SEM, n=8 vials -> SD = (55.1−53.2)·√8 = 5.4. Record: value 53.2 (reconstructed), SEM→SD conversion note, figure 2B, tool version, date. Sensitivity analysis: with and without this study.""",
 examples=[("Preclinical","Lifespan bar charts."),("Plant","Biomass bar plots."),("Clinical","Kaplan-Meier curves."),("Ecology","Scatter plots."),("Education","Test-score bars.")],
 mistakes=["Treating digitised data as reported.","No calibration record.","Assuming SE bars are SD.","Not asking authors.","Filling missing values with means."],
 misconceptions=[("'Digitising is exact.'","It has measurement error."),("'Missing means zero.'","Missing is unknown.")],
 controversies=["Use of reconstructed data in primary analyses.","Reporting of reconstruction uncertainty."],
 decision_tree=[("Numbers in text/table?","Use them."),("Only figure?","Digitise, label reconstructed."),("Unclear error bars?","Contact authors; else exclude/sensitivity."),("Nothing usable?","Missing + reason.")],
 exercises=["Digitise a published figure twice and compare values.","Draft an author data-request email (template in Network).","Plan a sensitivity analysis for reconstructed values."],
 integrity="Never fabricate unavailable observations; label reconstructed values with method and uncertainty; contact authors only with your approval.",
 further=["drevon2016","wan2014","mathes2017"], application="**Milestone 7:** list values needing reconstruction; digitise with records; plan sensitivity.",
 checklist=["Calibration recorded","Values labelled reconstructed","Error-bar type verified","Authors contacted (with approval)","Sensitivity analysis planned"],
 quiz=[dict(q="Digitised values should be labelled...", opts=["Reported","Reconstructed (with method)","Verified","Imputed"], ans=1, why="Provenance."),
  dict(q="SEM bar read as 1.9 above mean, n=8 vials. SD?", opts=["5.4","1.9","0.67","15.2"], ans=0, why="1.9×√8=5.37.", numeric=True),
  dict(q="If nothing usable is available:", opts=["Guess","Record missing with reason","Use mean of others","Delete the study silently"], ans=1, why="Never invent."),
  dict(q="A sensitivity analysis for reconstructed data should...", opts=["Exclude/inflate uncertainty and compare","Be skipped","Hide data","Replace data"], ans=0, why="Test robustness."),
  dict(q="Before using digitised data you should...", opts=["Try contacting authors","Ignore authors","Assume exact","Skip logging"], ans=0, why="Prefer source data.")])

add(id=23, title="Risk-of-bias visualisation and use in synthesis", last_verified=V, prerequisites=["Module 22"],
 objectives=["Create traffic-light and summary plots accessibly.", "Use RoB results in pre-specified sensitivity analyses.", "Present disagreements and unclear judgements honestly."],
 why="Readers rely on plots to judge reliability; poor visualisation hides problems.",
 plain="""Two standard plots: a **traffic-light** matrix (studies × domains) and a **summary bar chart** (proportion low/unclear/high per domain). robvis (McGuinness & Higgins 2020) produces these for common tools. Make them accessible: print judgements as text in cells, not colour alone. Always show *unclear* as its own category.""",
 intermediate="""Use RoB in the synthesis as *pre-specified*: sensitivity analysis excluding high-risk studies, subgroup by risk, or certainty downgrading (Module 52). Do not remove studies post hoc. With many 'unclear' judgements due to poor reporting, an 'exclude unclear/high' analysis may leave too few studies; plan for that.""",
 advanced="""Domain-level versus overall judgements: overall rules are tool-specific. Outcome-level assessments produce a matrix per outcome. Visual summaries can hide heterogeneity within domains - provide supporting text in supplements (quotes/page numbers).""",
 assumptions=["Judgements and rationale are recorded.","Tool-specific overall rules are followed."],
 worked_example="""Matrix of 3 studies × 2 domains: S001 low/low; S002 unclear/unclear; S003 unclear/high. Summary: random housing 1 low, 2 unclear; blinding 1 low, 1 unclear, 1 high. Pre-specified sensitivity: re-run the pooled analysis excluding S003 (high risk) and report both results, whatever they are.""",
 examples=[("Preclinical","SYRCLE plots."),("Clinical","RoB 2 plots."),("Observational","ROBINS-I plots."),("Diagnostic","QUADAS-2 plots."),("Custom","Custom-domain plots.")],
 mistakes=["Colour-only plots.","Unclear merged into low.","Post-hoc exclusions.","No rationale."],
 misconceptions=[("'Green means no bias.'","Low risk is a judgement, not absence."),("'Summary plots are enough.'","Provide rationale.")],
 controversies=["Overall judgements.","Use in sensitivity analyses."],
 decision_tree=[("Judgements complete with rationale?","Plot."),("Many unclear?","Report; limit sensitivity interpretation."),("Pre-specified analysis?","Run and report both.")],
 exercises=["Plot RoB for the Virtual Lab studies.","Write a plot caption with abbreviations.","Add text labels for colour-blind readers."],
 integrity="Show unclear and high judgements prominently; do not select plots that look best.", further=["mcguinness2020","hooijmans2014","sterne2019rob2"],
 application="**Milestone 8:** produce RoB plots with accessible text and supplemental rationale.", checklist=["Accessible plots","Rationale supplied","Pre-specified sensitivity run"],
 quiz=[dict(q="Why add text to plot cells?", opts=["Accessibility for colour-blind readers","Decoration","Journals","Speed"], ans=0, why="Not colour only."),
  dict(q="Unclear judgements should be...", opts=["Merged into low","Shown as unclear","Hidden","Deleted"], ans=1, why="Honest reporting."),
  dict(q="Excluding high-risk studies should be...", opts=["Pre-specified sensitivity analysis","Post hoc","Never","Only if significant"], ans=0, why="Avoid selection."),
  dict(q="robvis creates...", opts=["Traffic-light and summary plots","Forest plots only","Databases","Registries"], ans=0, why="McGuinness 2020."),
  dict(q="Supplementary rationale is...", opts=["Useful for transparency","Unnecessary","Forbidden","A figure"], ans=0, why="Supports judgements.")])

add(id=28, title="Binary outcomes: RR, OR, RD, NNT and zero cells", last_verified=V, prerequisites=["Module 27"],
 objectives=["Compute RR, OR, RD, NNT and their variances from 2×2 data.", "Explain why OR ≠ RR when events are common.", "Handle zero cells and rare events appropriately."],
 why="Binary outcomes (survival to day X, infection, germination) are everywhere; the choice of measure changes interpretation, and zero cells break naive formulas.",
 plain="""From a 2×2 table (events and non-events in treated and control): **risk ratio (RR)** = risk_treated / risk_control; **odds ratio (OR)** = odds_treated / odds_control; **risk difference (RD)** = risk_treated − risk_control; **NNT** = 1/|RD| (number needed to treat per extra outcome). RR and OR are analysed on the log scale. When events are rare OR≈RR; when common they diverge, and OR exaggerates relative effects.""",
 intermediate="""Variances: ln RR: 1/a − 1/n₁ + 1/c − 1/n₂; ln OR: 1/a+1/b+1/c+1/d; RD: p₁(1−p₁)/n₁ + p₂(1−p₂)/n₂. **Zero cells** make logs undefined; a continuity correction (e.g. +0.5 to every cell of the study) is a convention with known drawbacks (Sweeting et al. 2004), and for sparse data Mantel-Haenszel or Peto methods (which need no correction) or model-based approaches may be preferable (Bradburn et al. 2007; Module 33/48). Double-zero studies carry no information on relative effects in most methods.
**NNT** is not constant across baseline risks; derive absolute effects from a representative baseline risk and the pooled relative effect.""",
 advanced="""Collapsibility: ORs are non-collapsible - an adjusted OR differs from the marginal OR even without confounding; RR and RD are collapsible. Meta-analysing different measures (OR and RR) mixes scales; convert only with explicit baseline risk. Choosing the measure post hoc by significance is a protocol violation.""",
 assumptions=["Independent groups.", "Events and n counted at the independent-unit level.", "Measure pre-specified."],
 formulas=[dict(name="Log OR and variance", tex=r"\ln OR=\ln\frac{ad}{bc},\quad v=\frac1a+\frac1b+\frac1c+\frac1d", symbols={"a,b":"treated events/non-events","c,d":"control events/non-events"}),
   dict(name="Log RR and variance", tex=r"\ln RR=\ln\frac{a/n_1}{c/n_2},\quad v=\frac1a-\frac1{n_1}+\frac1c-\frac1{n_2}", symbols={"n_1,n_2":"group sizes"}),
   dict(name="RD and NNT", tex=r"RD=\frac{a}{n_1}-\frac{c}{n_2},\quad NNT=\frac1{|RD|}", symbols={"RD":"risk difference"})],
 worked_example="""Treated 15/100 events, control 25/100. RR = 0.15/0.25 = **0.60**; OR = (15/85)/(25/75) = **0.529**; RD = **−0.10**; NNT = **10**. ln RR variance = 1/15 − 1/100 + 1/25 − 1/100 = **0.0867**; ln OR variance = 1/15+1/85+1/25+1/75 = **0.1318**. Zero cell: 0/20 vs 3/20 -> with +0.5: ln OR = ln((0.5·17.5)/(20.5·3.5)) = −2.10 (illustrative; sensitive to the correction).""",
 examples=[("Clinical","Mortality at 28 days."),("Preclinical","Survival to a time point."),("Plant","Germination (events/seeds - unit = plate)."),("Microbiology","Detection/no detection."),("Education","Pass/fail with clustering.")],
 mistakes=["Reading OR as RR for common outcomes.","Adding 0.5 without sensitivity analysis.","Using seeds not plates as n.","Mixing OR and RR.","NNT without baseline risk."],
 misconceptions=[("'OR and RR are interchangeable.'","Only for rare events."),("'Zero events means no risk.'","Absence of events in small samples is weak evidence.")],
 controversies=["Continuity corrections vs MH/Peto/GLMM.","Choice of OR vs RR in meta-analysis."],
 decision_tree=[("Events common?","Prefer RR/RD for interpretability."),("Events rare/zero cells?","MH/Peto or model-based; sensitivity."),("Absolute effect wanted?","Apply RR to baseline risk.")],
 exercises=["Compute RR, OR, RD, NNT for 12/60 vs 20/60 and check the calculator.","Explain why OR exaggerates RR here.","Run MH and Peto on the BCG data in the Statistics Lab."],
 integrity="Pre-specify the measure and correction rule; report sensitivity to corrections.", further=["sweeting2004","bradburn2007","higgins2011rob","viechtbauer2010"],
 coding=dict(r='library(metafor)\nescalc(measure="RR", ai=15, n1i=100, ci=25, n2i=100)\nescalc(measure="OR", ai=15, n1i=100, ci=25, n2i=100)\nescalc(measure="RD", ai=15, n1i=100, ci=25, n2i=100)', python='from metalab import stats as S\nprint(S.log_risk_ratio(15,100,25,100))    # (-0.5108, 0.0867)\nprint(S.log_odds_ratio(15,100,25,100))    # (-0.6360, 0.1318)\nprint(S.risk_difference(15,100,25,100))   # (-0.10, ...)'),
 application="**Milestone 9:** choose the binary measure and correction rule in the SAP; compute effects with the calculators; run MH/Peto sensitivity.", checklist=["Measure pre-specified","Zero-cell rule stated","Unit of analysis correct","Sensitivity done"],
 quiz=[dict(q="Treated 15/100, control 25/100. RR?", opts=["0.60","0.53","-0.10","10"], ans=0, why="0.15/0.25.", numeric=True),
  dict(q="Same data: odds ratio?", opts=["0.529","0.60","0.40","1.9"], ans=0, why="(15/85)/(25/75)=0.529.", numeric=True),
  dict(q="Same data: NNT?", opts=["10","100","4","0.1"], ans=0, why="1/0.10.", numeric=True),
  dict(q="When do OR and RR approximate each other?", opts=["Rare events","Common events","Never","Always"], ans=0, why="Odds≈risk when risks are small."),
  dict(q="Sparse data with zero cells: consider...", opts=["MH/Peto or model-based methods and sensitivity analyses","Ignore","Delete studies","Add 5"], ans=0, why="Bradburn 2007; Sweeting 2004.")])

add(id=31, title="Effect-size transformations: what can and cannot be converted", last_verified=V, prerequisites=["Modules 18, 27, 28"],
 objectives=["Convert SD/SE/CI/p-value/test statistics when valid.", "Recognise invalid conversions.", "Harmonise direction and scales."],
 why="Most extraction problems are conversion problems. Valid conversions rescue studies; invalid ones create false precision.",
 plain="""Valid (with assumptions): SD↔SE using n; CI→SE using the right quantile; exact two-sided p-value → SE (|estimate|/z or t); combine groups; flip direction. Invalid or risky: a p-value reported only as 'p<0.05'; converting medians to means without distribution assumptions; mixing OR and RR; using fly counts as n; transforming between SMD and log OR without justification.""",
 intermediate="""**p→SE**: SE = |estimate|/z where z=Φ⁻¹(1−p/2) (t with df for small samples). Requires an *exact* two-sided p-value for the *same* estimate; rounded p near 0.05 gives large errors. **CI→SE**: SE=(U−L)/(2·crit), logs for ratios, t for small n. **Direction**: multiply by −1 when lower is better. **Units**: convert before pooling (hours→days). Label converted values as *calculated* or *estimated* in extraction.""",
 advanced="""Error propagation: rounding in reported CIs and p-values creates uncertainty in the recovered SE; check plausibility (e.g. CV). For log-scale ratio measures convert CI limits on the log scale. Conversions between effect-size families (d↔OR via logistic approximations) rely on distributional assumptions and are rarely justified for primary analyses.""",
 assumptions=["Exact values, symmetric intervals, stated test type."],
 worked_example="""Estimate 0.50 with exact two-sided p = 0.05 -> z = 1.96 -> SE = 0.50/1.96 = **0.255**. With n=10 per group (df 18) t=2.101 -> SE = 0.238. If only 'p<0.05' is reported, no SE can be recovered. Hours→days: 1176 h = 49 d. SEM→SD: 1.2×√8 = 3.39.""",
 examples=[("Clinical","HR CI on log scale."),("Preclinical","Lifespan hours/days."),("Ecology","Reported t-statistics."),("Education","Cohen's d from t."),("Psychology","Correlations to Fisher z.")],
 mistakes=["Using 'p<0.05' as p=0.05.","Converting without logs.","Forgetting direction.","Mixing units.","Not labelling conversions."],
 misconceptions=[("'Any p-value gives an SE.'","Only exact two-sided ones."),("'A conversion is as good as reported data.'","It adds uncertainty.")],
 controversies=["Acceptability of estimated SDs.","Cross-family conversions."],
 decision_tree=[("Exact p and estimate?","SE = est/z."),("Inequality only?","Not convertible."),("Ratio measure?","Work on log scale."),("Different units?","Convert first.")],
 exercises=["Convert five reported statistics to SE with the calculators.","Explain why 'p<0.05' cannot be converted.","List conversions your review needs."],
 integrity="Label converted/estimated values; never use a conversion outside its assumptions.", further=["wan2014","higgins2011rob","borenstein2009book"],
 coding=dict(r='est <- 0.5; p <- 0.05\nabs(est)/qnorm(1 - p/2)      # 0.2551\nabs(est)/qt(1 - p/2, 18)    # 0.2380', python='from metalab import stats as S\nprint(S.se_from_p(0.5, 0.05), S.se_from_p(0.5, 0.05, df=18))   # 0.2551 0.2380'),
 application="**Milestone 7/9:** list conversions needed; apply only valid ones; label them.", checklist=["Conversions valid","Labelled","Units/direction harmonised","Sensitivity planned"],
 quiz=[dict(q="Estimate 0.50 with exact two-sided p=0.05. SE (normal)?", opts=["0.255","0.05","0.50","1.96"], ans=0, why="0.5/1.96.", numeric=True),
  dict(q="A paper reports 'p<0.05'. SE?", opts=["Computable exactly","Not recoverable","0.05","Zero"], ans=1, why="Inequality."),
  dict(q="For ratio measures convert CI limits...", opts=["On the log scale","On the raw scale","Not at all","By averaging"], ans=0, why="Symmetry on log scale."),
  dict(q="1176 hours in days?", opts=["49","24","1176","98"], ans=0, why="÷24.", numeric=True),
  dict(q="Converted values should be labelled...", opts=["Calculated/estimated","Reported","Verified","Raw"], ans=0, why="Provenance.")])
